    [1, 3, 4, X, X, X, 4, X],
    [0, 1, X, 4, X, X, X, 3],
    [0, 1, 2, X, 2, 3, X, 2]
]

rows = len(game_data)
cols = len(game_data[0])

# Model definition
model = cp_model.CpModel()

# Decision Variables: mines[i][j] = 1 if cell (i,j) is a mine, 0 otherwise
mines = []
for i in range(rows):
    row = []
    for j in range(cols):
        if game_data[i][j] == X:
            var = model.NewBoolVar(f"mine_{i}_{j}")
        else:
            var = model.NewConstant(0)  # Opened cells cannot be mines
        row.append(var)
    mines.append(row)

# Constraints
for i in range(rows):
    for j in range(cols):
        if game_data[i][j] != X:
            # For each opened cell, the sum of mines in its 8 neighbors must equal the clue
            neighbors = []
            for di in [-1, 0, 1]:
                for dj in [-1, 0, 1]:
                    if di == 0 and dj == 0:
                        continue
                    ni, nj = i + di, j + dj
                    if 0 <= ni < rows and 0 <= nj < cols:
                        neighbors.append(mines[ni][nj])
            model.Add(sum(neighbors) == game_data[i][j])

