import json
import itertools

# Input data
n_weeks = 4      # Number of weeks
n_groups = 3     # Number of groups per week
group_size = 3   # Size of each group
n_golfers = n_groups * group_size

# Model definition
model = cp_model.CpModel()

# Decision Variables:
# assign[w][g][s]: golfer assigned to slot s in group g in week w
assign = []
for w in range(n_weeks):
    week = []
    for g in range(n_groups):
        group = []
        for s in range(group_size):
            var = model.NewIntVar(0, n_golfers - 1, f'assign_w{w}_g{g}_s{s}')
            group.append(var)
        week.append(group)
    assign.append(week)

# 1. Each group in each week has unique golfers (no duplicates in a group)
for w in range(n_weeks):
    for g in range(n_groups):
        model.AddAllDifferent(assign[w][g])

# 2. Each golfer plays exactly once per week
for w in range(n_weeks):
    for golfer in range(n_golfers):
        # For each week, golfer must appear exactly once
        occurrences = []
        for g in range(n_groups):
            for s in range(group_size):
                occurrences.append(assign[w][g][s])
        model.AddExactlyOne([occ == golfer for occ in occurrences])

# 3. No pair of golfers plays together more than once
# For each pair of golfers, count the number of weeks they are together in a group, must be <= 1
pair_played_together = {}
for g1 in range(n_golfers):
    for g2 in range(g1 + 1, n_golfers):
        together_in_weeks = []
        for w in range(n_weeks):
            # For each group, check if both are in the same group
            for g in range(n_groups):
                # Both g1 and g2 in group g in week w
                bools = []
                for s1 in range(group_size):
                    for s2 in range(group_size):
                        if s1 != s2:
                            b1 = model.NewBoolVar(f'g1_{g1}_w{w}_g{g}_s{s1}')
                            b2 = model.NewBoolVar(f'g2_{g2}_w{w}_g{g}_s{s2}')
                            model.Add(assign[w][g][s1] == g1).OnlyEnforceIf(b1)
                            model.Add(assign[w][g][s1] != g1).OnlyEnforceIf(b1.Not())
                            model.Add(assign[w][g][s2] == g2).OnlyEnforceIf(b2)
                            model.Add(assign[w][g][s2] != g2).OnlyEnforceIf(b2.Not())
                            both = model.NewBoolVar(f'both_{g1}_{g2}_w{w}_g{g}_s{s1}_{s2}')
                            model.AddBoolAnd([b1, b2]).OnlyEnforceIf(both)
                            model.AddBoolOr([b1.Not(), b2.Not()]).OnlyEnforceIf(both.Not())
                            bools.append(both)
                if bools:
                    in_group = model.NewBoolVar(f'in_group_{g1}_{g2}_w{w}_g{g}')
                    model.AddMaxEquality(in_group, bools)
                    together_in_weeks.append(in_group)
        if together_in_weeks:
            model.Add(sum(together_in_weeks) <= 1)

# Symmetry breaking: order golfers in first group of first week
for s in range(group_size - 1):
    model.Add(assign[0][0][s] < assign[0][0][s + 1])

# Solve the model
solver = cp_model.CpSolver()
solver.parameters.max_time_in_seconds = 60.0  # Limit time for feasibility
status = solver.Solve(model)

if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
    # Build the assignment as a 4-level list: weeks -> groups -> slots -> golfer
    assign_sol = []
    for w in range(n_weeks):
