from ortools.sat.python import cp_model
import json

# Input data
n_boats = 5  # Number of boats
n_periods = 4  # Number of periods
capacity = [6, 8, 12, 12, 12]  # Capacities of the boats
crew_size = [2, 2, 2, 2, 4]  # Crew sizes of the boats

model = cp_model.CpModel()

# Decision variables

# is_host[b]: 1 if boat b is a host, 0 otherwise
is_host = [model.NewBoolVar(f'is_host_{b}') for b in range(n_boats)]

# visits[g][h][t]: 1 if guest boat g visits host h at period t
# g != h, only guests can visit hosts
visits = []
for g in range(n_boats):
    visits_g = []
    for h in range(n_boats):
        visits_gh = []
        for t in range(n_periods):
            visits_gh.append(model.NewBoolVar(f'visits_g{g}_h{h}_t{t}'))
        visits_g.append(visits_gh)
    visits.append(visits_g)

# Constraints

# 1. A boat is either a host or a guest, not both
#    If a boat is a host, its crew never leaves; if guest, it never hosts
for b in range(n_boats):
    # If b is not a host, it must visit a host in every period
    for t in range(n_periods):
        # For each period, sum over all hosts h != b
        model.Add(
            sum(visits[b][h][t] for h in range(n_boats) if h != b) == (1 - is_host[b])
        )
    # A host never visits anyone
    for h in range(n_boats):
        for t in range(n_periods):
            if h != b:
                model.Add(visits[b][h][t] == 0).OnlyEnforceIf(is_host[b])

# 2. A guest cannot visit the same host more than once
for g in range(n_boats):
    for h in range(n_boats):
        if g != h:
            model.Add(sum(visits[g][h][t] for t in range(n_periods)) <= 1)

# 3. A guest cannot visit itself
for g in range(n_boats):
    for t in range(n_periods):
        model.Add(visits[g][g][t] == 0)

# 4. A host cannot host itself as a guest
for h in range(n_boats):
    for t in range(n_periods):
        model.Add(visits[h][h][t] == 0)

# 5. Capacity constraints: For each host h at each period t, the sum of its own crew and all visiting guest crews <= capacity
for h in range(n_boats):
    for t in range(n_periods):
        # Only if h is a host
        guest_sum = sum(visits[g][h][t] * crew_size[g] for g in range(n_boats) if g != h)
        model.Add(crew_size[h] + guest_sum <= capacity[h]).OnlyEnforceIf(is_host[h])
        # If not a host, no one can visit
        for g in range(n_boats):
            if g != h:
                model.Add(visits[g][h][t] == 0).OnlyEnforceIf(is_host[h].Not())

# 6. Guest crews cannot meet more than once
# For each pair of guest boats (g1, g2), count the number of periods and hosts where they are together
for g1 in range(n_boats):
    for g2 in range(g1 + 1, n_boats):
        if g1 != g2:
            meet_vars = []
            for h in range(n_boats):
                if h != g1 and h != g2:
                    for t in range(n_periods):
                        # Both g1 and g2 visit h at t
                        meet = model.NewBoolVar(f'meet_g{g1}_g{g2}_h{h}_t{t}')
                        model.AddBoolAnd([visits[g1][h][t], visits[g2][h][t]]).OnlyEnforceIf(meet)
                        model.AddBoolOr([visits[g1][h][t].Not(), visits[g2][h][t].Not()]).OnlyEnforceIf(meet.Not())
                        meet_vars.append(meet)
            model.Add(sum(meet_vars) <= 1)

# 7. A guest cannot visit the same host more than once (already enforced above)

# Objective: Minimize the number of host boats
model.Minimize(sum(is_host))

# Solve the model
solver = cp_model.CpSolver()
status = solver.Solve(model)

# Prepare output
if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
    # visits[g][h][t]: 1 if guest g visits host h at period t
    visits_out = [[[int(solver.Value(visits[g][h][t])) for t in range(n_periods)] for h in range(n_boats)] for g in range(n_boats)]
    is_host_out = [int(solver.Value(is_host[b])) for b in range(n_boats)]
    solution = {
        'visits': visits_out,
        'is_host': is_host_out
    }
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
